def add_default_hours_to_existing_facilities(apps, schema_editor):
    """Keep legacy listings usable without inventing weekend availability."""
    Facility = apps.get_model("coreApp", "Facility")
    FacilityAvailability = apps.get_model("coreApp", "FacilityAvailability")
    schedules = []
    for facility in Facility.objects.all().iterator():
        for day in range(7):
            is_weekday = 1 <= day <= 5
            schedules.append(
                FacilityAvailability(
                    facility_id=facility.pk,
                    day_of_week=day,
                    opens_at=datetime.time(8) if is_weekday else None,
                    closes_at=datetime.time(18) if is_weekday else None,
                    is_closed=not is_weekday,
                )
            )
    FacilityAvailability.objects.bulk_create(schedules)


